def fill_folder(apps, schema_editor):
    Game = apps.get_model("library", "Game")
    # Folder gry to zawsze <system>/<katalog gry> — dokładnie tak grupuje skaner,
    # więc głębsze ścieżki (psx/FF7/disc1/…) też muszą dać "psx/FF7". Inaczej
    # pierwszy skan po migracji nigdy by się nie zbiegł.
    seen: set[str] = set()
    for game in Game.objects.order_by("pk").prefetch_related("files"):
        files = list(game.files.all())
        if not files:
            continue
        first = min(files, key=lambda f: f.relative_path)
        parts = first.relative_path.split("/")
        # Plik bezpośrednio w katalogu systemu (dwa segmenty) → gra luzem: folder zostaje "".
        if len(parts) < 3:
            continue
        folder = "/".join(parts[:2])
        # Dwie stare gry w jednym katalogu — folder jest unikalny, więc bierze go
        # pierwsza; druga zostaje z "" i skan przepnie jej plik do tej pierwszej.
        if folder in seen:
            continue
        seen.add(folder)
        game.folder = folder
        game.save(update_fields=["folder"])


